import Phaser from 'phaser';
import type { Character } from './Character';
import type { AbilityConfig } from '../types/ability';
import type { GameEntity } from './GameEntity';
import { MaharagaSummon } from './MaharagaSummon';
import type { ThreeArenaStage } from '../vfx/ThreeArenaStage';
import type { Vfx3DShape } from '../vfx/ThreeAbilityVfx';

/**
 * AbilityExecutor — generic data-driven ability engine powered by Phaser Physics + Three.js 3D WebGL2 VFX.
 *
 * Supports all 15 ABILITY_TYPES generated by CharacterAwakeningService or defined in ROSTER:
 * PROJECTILE, MOVEMENT, MELEE, BARRIER, SUMMON, AREA_DENIAL, BUFF, DEBUFF,
 * RESOURCE_DRAIN, COUNTER, TERRAIN, TRANSFORMATION, EXECUTION, TETHER, COMMAND.
 */
export class AbilityExecutor {
  character: Character;

  constructor(character: Character) {
    this.character = character;
  }

  private get threeVfx() {
    return ((this.character.scene as any).threeStage as ThreeArenaStage | undefined)?.abilityVfx;
  }

  private _resolveDamage(config: AbilityConfig, fallback = 24): number {
    return config.damage ?? config.payload?.damage ?? fallback;
  }

  private _resolveColor(config?: AbilityConfig): string {
    return (
      config?.payload?.vfx3d?.primaryColor ||
      this.character.visualProfile?.casterColor ||
      this.character.visualProfile?.color ||
      '#38bdf8'
    );
  }

  private _resolveColorNum(config?: AbilityConfig): number {
    const hex = this._resolveColor(config).replace('#', '');
    const parsed = parseInt(hex, 16);
    return Number.isNaN(parsed) ? 0x38bdf8 : parsed;
  }

  /** Entry point — called from PlayerCharacter / CPUCharacter after AbilityManager.activate(). */
  execute(slot: string) {
    const state = this.character.abilityManager?.slots.get(slot);
    if (!state) return;

    const config = state.config;
    const scene = this.character.scene as any;
    const target = scene.getOpponentOf?.(this.character) as GameEntity | undefined;

    // Trigger character's 2D particle vocabulary if present
    scene.vfx?.execute?.('onActivation', this.character.visualProfile, {
      caster: this.character.sprite,
      target: target?.sprite,
      x: this.character.sprite.x,
      y: this.character.sprite.y
    });

    switch (config.type) {
      case 'MOVEMENT':       this._executeMovement(config, target); break;
      case 'DEBUFF':         this._executeDebuff(config, target); break;
      case 'EXECUTION':      this._executeExecution(config, target); break;
      case 'MELEE':          this._executeMelee(config, target); break;
      case 'PROJECTILE':     this._executeProjectile(config, target); break;
      case 'BUFF':           this._executeBuff(config); break;
      case 'SUMMON':         this._executeSummon(config, target); break;
      case 'BARRIER':        this._executeBarrier(config, target); break;
      case 'AREA_DENIAL':    this._executeAreaDenial(config, target); break;
      case 'RESOURCE_DRAIN': this._executeResourceDrain(config, target); break;
      case 'COUNTER':        this._executeCounter(config, target); break;
      case 'TERRAIN':        this._executeTerrain(config, target); break;
      case 'TRANSFORMATION': this._executeTransformation(config); break;
      case 'TETHER':         this._executeTether(config, target); break;
      case 'COMMAND':        this._executeCommand(config, target); break;
      default:
        this._executeProjectile(config, target);
    }
  }

  // ─────────────────────────────────────────────────────────────
  //  1. SUMMON — spawn a shikigami / summon entity as a hitbox actor
  //  Supports CHASE | DIVE | BOSS and AI-generated spawnPosition/summonId
  // ─────────────────────────────────────────────────────────────
  private _executeSummon(config: AbilityConfig, target: GameEntity | undefined) {
    const { payload = {}, castTime = 350, archetype = 'SHADOW' } = config;
    const damage = this._resolveDamage(config, 32);
    const colorHex = this._resolveColor(config);
    const colorNum = this._resolveColorNum(config);

    // Map AI-generated spawnPosition / maxActive to CHASE | DIVE | BOSS if summonType wasn't explicitly set
    let subtype: string = payload.summonType;
    if (!subtype) {
      if (config.slot === 'Ability3' || (payload.cost?.cursedEnergy ?? 0) >= 75) subtype = 'BOSS';
      else if (payload.spawnPosition === 'NEAR_TARGET' || payload.spawnPosition === 'DIRECTED') subtype = 'DIVE';
      else subtype = 'CHASE';
    }

    const duration: number = payload.duration ?? 3500;
    const hbW: number = payload.hitboxWidth ?? 44;
    const hbH: number = payload.hitboxHeight ?? 44;
    const owner = this.character;
    const scene = owner.scene as any;

    owner.isAttacking = true;

    // 3D Shadow/Cursed Portal under caster
    this.threeVfx?.spawnAreaZone({
      x: owner.sprite.x,
      y: owner.sprite.y,
      radiusPx: 75,
      durationMs: castTime + 700,
      color: colorHex
    });
    this._voidBurst(owner.sprite.x, owner.sprite.y, colorNum, 50);
    this._floatingText(owner.sprite.x, owner.sprite.y - 55, config.name, colorHex);

    scene.time.delayedCall(castTime, () => {
      if (!owner.isAlive) { owner.isAttacking = false; return; }

      if (subtype === 'CHASE' && target) {
        const count: number = payload.count ?? payload.maxActive ?? 1;
        for (let i = 0; i < count; i++) {
          scene.time.delayedCall(i * 180, () => {
            this._spawnChaseSummon(target, hbW, hbH, damage, duration, config, archetype);
          });
        }
      } else if (subtype === 'DIVE' && target) {
        this._spawnDiveSummon(target, hbW, hbH, damage, duration, config, archetype, payload.knockback);
      } else if (subtype === 'BOSS') {
        this._spawnBossSummon(target, hbW, hbH, damage, duration, config, archetype, payload.knockback);
      }

      scene.time.delayedCall(400, () => { owner.isAttacking = false; });
    });
  }

  // ─────────────────────────────────────────────────────────────
  //  2. MOVEMENT — 3D spatial warp dash + strike
  // ─────────────────────────────────────────────────────────────
  private _executeMovement(config: AbilityConfig, target: GameEntity | undefined) {
    const { payload = {}, castTime = 120 } = config;
    const damage = this._resolveDamage(config, 22);
    const range: number = payload.range ?? 380;
    const invDuration: number = payload.invincibleDuration ?? 280;
    const subtype: string = payload.movementSubtype ?? 'TARGET_RELATIVE';
    const owner = this.character;
    const scene = owner.scene as any;
    const colorHex = this._resolveColor(config);
    const colorNum = this._resolveColorNum(config);

    const startX = owner.sprite.x;
    const startY = owner.sprite.y;
    const facingDir = owner.sprite.flipX ? -1 : 1;

    let landX = startX + facingDir * Math.min(range, 280);
    let dir = facingDir;

    if (target?.sprite && subtype === 'TARGET_RELATIVE') {
      const dx = target.sprite.x - startX;
      dir = dx >= 0 ? 1 : -1;
      if (Math.abs(dx) <= range) {
        landX =
          payload.relativePosition === 'BEHIND'
            ? target.sprite.x + dir * 42
            : target.sprite.x - dir * 38;
      } else {
        // Dash maximum range toward target instead of failing
        landX = startX + dir * range;
      }
    }

    landX = Phaser.Math.Clamp(landX, 50, scene.scale.width - 50);

    owner.isAttacking = true;
    this._floatingText(startX, startY - 50, config.name, colorHex);

    scene.time.delayedCall(castTime, () => {
      if (!owner.isAlive) { owner.isAttacking = false; return; }

      // Render 3D Spatial Warp Tunnel along the dash path
      this.threeVfx?.spawnDash({
        fromX: startX,
        fromY: startY,
        toX: landX,
        toY: owner.sprite.y,
        color: colorHex
      });

      owner.sprite.setPosition(landX, owner.sprite.y);
      owner.sprite.setFlipX(dir === -1);

      owner.immunities.add('PHYSICAL');
      scene.time.delayedCall(invDuration, () => owner.immunities.delete('PHYSICAL'));

      // Arrival hitbox + 3D slash arc
      this._spawnHitbox(landX + dir * 24, owner.sprite.y, dir, 56, 64, damage, config);
      this.threeVfx?.spawnSlash({
        x: landX + dir * 24,
        y: owner.sprite.y,
        dir,
        widthPx: 64,
        heightPx: 64,
        color: colorHex
      });

      this._voidBurst(landX, owner.sprite.y, colorNum, 32);
      if (target) this._applyStatusEffects(config, target);

      scene.time.delayedCall(260, () => { owner.isAttacking = false; });
    });
  }

  // ─────────────────────────────────────────────────────────────
  //  3. DEBUFF — stackable cursed marks + 3D Tether & Vortex
  // ─────────────────────────────────────────────────────────────
  private _executeDebuff(config: AbilityConfig, target: GameEntity | undefined) {
    const { slot, payload = {}, castTime = 350 } = config;
    const damage = this._resolveDamage(config, 20);
    const maxStacks: number = payload.maxStacks ?? 3;
    const stackDuration: number = payload.duration ?? 6000;
    const burstDamage: number = payload.onMaxStacks?.burstDamage ?? 45;
    const stackKey = `${this.character.id}:${slot}`;
    const owner = this.character;
    const scene = owner.scene as any;
    const colorHex = this._resolveColor(config);
    const colorNum = this._resolveColorNum(config);

    if (!target?.sprite) return;

    owner.isAttacking = true;
    this.threeVfx?.spawnTether({
      getCasterPos: () => ({ x: owner.sprite.x, y: owner.sprite.y, active: owner.isAlive }),
      getTargetPos: () => ({ x: target.sprite.x, y: target.sprite.y, active: target.isAlive }),
      durationMs: castTime + 250,
      color: colorHex
    });

    scene.time.delayedCall(castTime, () => {
      if (!owner.isAlive || !target.isAlive) { owner.isAttacking = false; return; }

      const current = target.debuffStacks.get(stackKey) ?? 0;

      if (current >= maxStacks) {
        this._detonateStacks(target, stackKey, burstDamage, config);
        owner.isAttacking = false;
        return;
      }

      const newCount = current + 1;
      target.debuffStacks.set(stackKey, newCount);

      this.threeVfx?.spawnAreaZone({
        x: target.sprite.x,
        y: target.sprite.y,
        radiusPx: 45 + newCount * 15,
        durationMs: 750,
        color: colorHex
      });
      this._voidBurst(target.sprite.x, target.sprite.y, colorNum, 38 + newCount * 10);
      this._floatingText(target.sprite.x, target.sprite.y - 50, `${config.name} ×${newCount}`, colorHex);

      if (damage > 0) {
        const dir = owner.sprite.x < target.sprite.x ? 1 : -1;
        const actualDmg = target.receiveDamage(damage, config.archetype ?? 'VOID', owner);
        if (actualDmg > 0) {
          owner.onDamageDealt?.(actualDmg);
          (target.sprite.body as Phaser.Physics.Arcade.Body)?.setVelocity(200 * dir, -150);
        }
      }

      this._applyStatusEffects(config, target);

      scene.time.delayedCall(stackDuration, () => {
        const c = target.debuffStacks.get(stackKey) ?? 0;
        if (c > 0) target.debuffStacks.set(stackKey, c - 1);
      });

      if (newCount >= maxStacks && burstDamage > 0) {
        scene.time.delayedCall(350, () => {
          this._detonateStacks(target, stackKey, burstDamage, config);
        });
      }

      owner.isAttacking = false;
    });
  }

  // ─────────────────────────────────────────────────────────────
  //  4. EXECUTION — 3D Singularity Collapse (stack detonation OR HP threshold)
  // ─────────────────────────────────────────────────────────────
  private _executeExecution(config: AbilityConfig, target: GameEntity | undefined) {
    const { payload = {}, castTime = 650 } = config;
    const baseDamage = this._resolveDamage(config, 55);
    const owner = this.character;
    const scene = owner.scene as any;
    const colorHex = this._resolveColor(config);
    const colorNum = this._resolveColorNum(config);

    owner.isAttacking = true;
    this._floatingText(owner.sprite.x, owner.sprite.y - 60, config.name, colorHex);
    this._voidBurst(owner.sprite.x, owner.sprite.y, colorNum, 70);

    scene.time.delayedCall(castTime, () => {
      if (!owner.isAlive) { owner.isAttacking = false; return; }

      const stackKey = this._findOwnedStackKey(target);
      const stacks = target ? (target.debuffStacks.get(stackKey) ?? 0) : 0;
      const hpRatio = target ? target.currentHp / Math.max(1, target.maxHp) : 1;
      const threshold = payload.hpThreshold ?? 0.35;
      const thresholdMet = target && hpRatio <= threshold;

      if (!target) {
        owner.isAttacking = false;
        return;
      }

      if (stacks > 0 || thresholdMet) {
        const bonusMult = stacks > 0 ? 1 + stacks * 0.3 : 1.35;
        const totalDmg = Math.round((payload.onThresholdMet?.damage ?? baseDamage) * bonusMult);
        if (stacks > 0) target.debuffStacks.set(stackKey, 0);

        this.threeVfx?.spawnSingularity({
          x: target.sprite.x,
          y: target.sprite.y,
          stacks: Math.max(2, stacks),
          color: colorHex
        });
        this._voidCollapse(target.sprite.x, target.sprite.y, Math.max(2, stacks));

        const actualDmg = target.receiveDamage(totalDmg, config.archetype ?? 'VOID', owner);
        if (actualDmg > 0) {
          owner.onDamageDealt?.(actualDmg);
          (target.sprite.body as Phaser.Physics.Arcade.Body)?.setVelocity(
            owner.sprite.x < target.sprite.x ? 600 : -600,
            -500
          );
        }

        this._applyStatusEffects(config, target);
        this._floatingText(target.sprite.x, target.sprite.y - 80, `${config.name}! -${totalDmg}`, colorHex);
      } else {
        // Reduced execution strike (or stackless execution) so AI characters without stack abilities still land a heavy 3D strike
        const fallbackDmg = payload.onThresholdNotMet?.damage ?? Math.round(baseDamage * 0.6);
        this.threeVfx?.spawnSingularity({
          x: target.sprite.x,
          y: target.sprite.y,
          stacks: 1,
          color: colorHex
        });
        const actualDmg = target.receiveDamage(fallbackDmg, config.archetype ?? 'VOID', owner);
        if (actualDmg > 0) owner.onDamageDealt?.(actualDmg);
        this._floatingText(target.sprite.x, target.sprite.y - 65, `${config.name} (${fallbackDmg})`, colorHex);
      }

      scene.time.delayedCall(350, () => { owner.isAttacking = false; });
    });
  }

  // ─────────────────────────────────────────────────────────────
  //  5. MELEE — 3D Crescent Slash Wave + Directional Hitbox
  // ─────────────────────────────────────────────────────────────
  private _executeMelee(config: AbilityConfig, target: GameEntity | undefined) {
    const { payload = {}, castTime = 100 } = config;
    const damage = this._resolveDamage(config, 28);
    const hbW: number = payload.hitboxWidth ?? 70;
    const hbH: number = payload.hitboxHeight ?? 70;
    const offsetX: number = payload.hitboxOffsetX ?? (22 + hbW / 2);
    const owner = this.character;
    const scene = owner.scene as any;
    const colorHex = this._resolveColor(config);

    owner.isAttacking = true;
    this._floatingText(owner.sprite.x, owner.sprite.y - 50, config.name, colorHex);

    scene.time.delayedCall(castTime, () => {
      if (!owner.isAlive) { owner.isAttacking = false; return; }
      const dir = owner.sprite.flipX ? -1 : 1;
      const hx = owner.sprite.x + dir * offsetX;
      const hy = owner.sprite.y;

      this._spawnHitbox(hx, hy, dir, hbW, hbH, damage, config);
      this.threeVfx?.spawnSlash({
        x: hx,
        y: hy,
        dir,
        widthPx: hbW,
        heightPx: hbH,
        color: colorHex
      });

      if (target) this._applyStatusEffects(config, target);
      scene.time.delayedCall(280, () => { owner.isAttacking = false; });
    });
  }

  // ─────────────────────────────────────────────────────────────
  //  6. PROJECTILE — 3D Glowing Orb / Cursed Spear / Barrage
  // ─────────────────────────────────────────────────────────────
  private _executeProjectile(config: AbilityConfig, target: GameEntity | undefined) {
    const { payload = {}, castTime = 120 } = config;
    const damage = this._resolveDamage(config, 24);
    const speed: number = payload.speed ?? 480;
    const count: number = Math.min(5, Math.max(1, payload.count ?? 1));
    const pw: number = payload.width ?? 28;
    const ph: number = payload.height ?? 28;
    const homing: boolean = Boolean(payload.homing);
    const shape: Vfx3DShape =
      payload.vfx3d?.shape ??
      (speed > 650 ? 'SPEAR' : pw > 45 ? 'METEOR' : 'SPHERE');

    const owner = this.character;
    const scene = owner.scene as any;
    const colorHex = this._resolveColor(config);

    owner.isAttacking = true;
    this._floatingText(owner.sprite.x, owner.sprite.y - 50, config.name, colorHex);

    scene.time.delayedCall(castTime, () => {
      if (!owner.isAlive) { owner.isAttacking = false; return; }

      const dir = owner.sprite.flipX ? -1 : 1;
      const lifetime = payload.range ? Math.max(600, (payload.range / speed) * 1000) : 2000;

      for (let i = 0; i < count; i++) {
        scene.time.delayedCall(i * 90, () => {
          if (!owner.isAlive) return;
          const spreadY = count > 1 ? (i - (count - 1) / 2) * 45 : 0;
          const startX = owner.sprite.x + dir * 34;
          const startY = owner.sprite.y - 8 + spreadY * 0.25;

          const proj = scene.hitboxes.create(startX, startY, undefined) as Phaser.Physics.Arcade.Sprite;
          proj.setVisible(false);
          proj.setDisplaySize(pw, ph);

          const body = proj.body as Phaser.Physics.Arcade.Body;
          body.setAllowGravity(false);
          body.setSize(pw, ph);
          body.setVelocity(speed * dir, spreadY);

          (proj as any).owner = owner;
          (proj as any).damage = damage;
          (proj as any).archetype = config.archetype ?? payload.archetype ?? 'VOID';
          (proj as any).facingDir = dir;

          // Attach 3D Three.js projectile mesh + point light
          this.threeVfx?.spawnProjectile({
            getPos: () => ({ x: proj.x, y: proj.y, active: Boolean(proj?.active) }),
            dir,
            color: colorHex,
            shape,
            radiusPx: Math.max(pw, ph),
            maxDurationMs: lifetime
          });

          // Optional homing steering
          let homingTimer: Phaser.Time.TimerEvent | undefined;
          if (homing && target?.sprite) {
            homingTimer = scene.time.addEvent({
              delay: 32,
              loop: true,
              callback: () => {
                if (!proj.active || !target.isAlive || !target.sprite) {
                  homingTimer?.remove();
                  return;
                }
                const angle = Phaser.Math.Angle.Between(proj.x, proj.y, target.sprite.x, target.sprite.y);
                body.setVelocity(Math.cos(angle) * speed, Math.sin(angle) * speed);
              }
            });
          }

          scene.time.delayedCall(lifetime, () => {
            homingTimer?.remove();
            if (proj?.active) proj.destroy();
          });
        });
      }

      scene.time.delayedCall(280, () => { owner.isAttacking = false; });
    });
  }

  // ─────────────────────────────────────────────────────────────
  //  7. BUFF — 3D Aura Awakening + Heal / Stat Boost
  // ─────────────────────────────────────────────────────────────
  private _executeBuff(config: AbilityConfig) {
    const { payload = {} } = config;
    const owner = this.character;
    const colorHex = this._resolveColor(config);
    const colorNum = this._resolveColorNum(config);
    const healAmount: number = payload.healAmount ?? 18;
    const duration: number = payload.duration ?? 5000;

    if (healAmount > 0) {
      owner.currentHp = Math.min(owner.maxHp, owner.currentHp + healAmount);
      this._floatingText(owner.sprite.x, owner.sprite.y - 50, `${config.name} +${healAmount} HP`, '#4ade80');
    } else {
      this._floatingText(owner.sprite.x, owner.sprite.y - 50, config.name, colorHex);
    }

    this.threeVfx?.spawnBarrier({
      getPos: () => ({ x: owner.sprite.x, y: owner.sprite.y, active: owner.isAlive }),
      radiusPx: 65,
      durationMs: Math.min(duration, 4000),
      color: colorHex
    });
    this._voidBurst(owner.sprite.x, owner.sprite.y, colorNum, 45);
  }

  // ─────────────────────────────────────────────────────────────
  //  8. BARRIER — 3D Geodesic Infinity Dome + Damage Mitigation & Repel
  // ─────────────────────────────────────────────────────────────
  private _executeBarrier(config: AbilityConfig, target: GameEntity | undefined) {
    const { payload = {} } = config;
    const owner = this.character;
    const scene = owner.scene as any;
    const colorHex = this._resolveColor(config);
    const radius: number = payload.radius ?? 95;
    const duration: number = payload.duration ?? 4000;

    this._floatingText(owner.sprite.x, owner.sprite.y - 55, config.name, colorHex);
    owner.immunities.add('PHYSICAL');

    this.threeVfx?.spawnBarrier({
      getPos: () => ({ x: owner.sprite.x, y: owner.sprite.y, active: owner.isAlive }),
      radiusPx: radius,
      durationMs: duration,
      color: colorHex
    });

    // Repel / slow nearby opponent entering the barrier radius
    const barrierTick = scene.time.addEvent({
      delay: 150,
      loop: true,
      callback: () => {
        if (!owner.isAlive || !target?.sprite) return;
        const dist = Phaser.Math.Distance.Between(owner.sprite.x, owner.sprite.y, target.sprite.x, target.sprite.y);
        if (dist <= radius * 1.15) {
          const pushDir = owner.sprite.x < target.sprite.x ? 1 : -1;
          (target.sprite.body as Phaser.Physics.Arcade.Body)?.setVelocityX(pushDir * 260);
        }
      }
    });

    scene.time.delayedCall(duration, () => {
      barrierTick.remove();
      owner.immunities.delete('PHYSICAL');
    });
  }

  // ─────────────────────────────────────────────────────────────
  //  9. AREA_DENIAL — 3D Swirling Cursed Glyph Vortex + Periodic Damage Ticks
  // ─────────────────────────────────────────────────────────────
  private _executeAreaDenial(config: AbilityConfig, target: GameEntity | undefined) {
    const { payload = {}, castTime = 250 } = config;
    const tickDamage = Math.max(6, Math.round(this._resolveDamage(config, 18) * 0.45));
    const radius: number = payload.radius ?? payload.width ?? 120;
    const duration: number = payload.duration ?? 4500;
    const tickRate: number = payload.tickRate ?? 600;
    const owner = this.character;
    const scene = owner.scene as any;
    const colorHex = this._resolveColor(config);

    const zoneX = target?.sprite ? target.sprite.x : owner.sprite.x + (owner.sprite.flipX ? -160 : 160);
    const zoneY = target?.sprite ? target.sprite.y : owner.sprite.y;

    this._floatingText(owner.sprite.x, owner.sprite.y - 55, config.name, colorHex);

    scene.time.delayedCall(castTime, () => {
      if (!owner.isAlive) return;

      this.threeVfx?.spawnAreaZone({
        x: zoneX,
        y: zoneY,
        radiusPx: radius,
        durationMs: duration,
        color: colorHex
      });

      const zoneTimer = scene.time.addEvent({
        delay: tickRate,
        loop: true,
        callback: () => {
          if (!target?.sprite || !target.isAlive) return;
          const dist = Phaser.Math.Distance.Between(zoneX, zoneY, target.sprite.x, target.sprite.y);
          if (dist <= radius * 1.15) {
            const actual = target.receiveDamage(tickDamage, config.archetype ?? 'VOID', owner);
            if (actual > 0) owner.onDamageDealt?.(actual);
            this._applyStatusEffects(config, target);
          }
        }
      });

      scene.time.delayedCall(duration, () => zoneTimer.remove());
    });
  }

  // ─────────────────────────────────────────────────────────────
  //  10. RESOURCE_DRAIN — 3D Siphon Helix + CE / HP Drain
  // ─────────────────────────────────────────────────────────────
  private _executeResourceDrain(config: AbilityConfig, target: GameEntity | undefined) {
    const { payload = {}, castTime = 250 } = config;
    const amount: number = payload.amount ?? 25;
    const resource: string = payload.resource ?? 'cursedEnergy';
    const owner = this.character;
    const scene = owner.scene as any;
    const colorHex = this._resolveColor(config);

    if (!target?.sprite) return;
    owner.isAttacking = true;

    this.threeVfx?.spawnTether({
      getCasterPos: () => ({ x: owner.sprite.x, y: owner.sprite.y, active: owner.isAlive }),
      getTargetPos: () => ({ x: target.sprite.x, y: target.sprite.y, active: target.isAlive }),
      durationMs: castTime + 650,
      color: colorHex
    });

    scene.time.delayedCall(castTime, () => {
      if (!owner.isAlive || !target.isAlive) { owner.isAttacking = false; return; }

      if (resource === 'cursedEnergy' && (target as any).cursedEnergy) {
        const drained = Math.min((target as any).cursedEnergy.current, amount);
        (target as any).cursedEnergy.current -= drained;
        if (payload.transferToSelf !== false) {
          owner.cursedEnergy.current = Math.min(owner.cursedEnergy.max, owner.cursedEnergy.current + drained);
        }
        this._floatingText(target.sprite.x, target.sprite.y - 55, `-${Math.round(drained)} CE`, colorHex);
      } else {
        const dmg = target.receiveDamage(amount, config.archetype ?? 'VOID', owner);
        if (dmg > 0 && payload.transferToSelf !== false) {
          owner.currentHp = Math.min(owner.maxHp, owner.currentHp + Math.round(dmg * 0.6));
        }
        this._floatingText(target.sprite.x, target.sprite.y - 55, `DRAIN -${amount}`, colorHex);
      }

      this._applyStatusEffects(config, target);
      owner.isAttacking = false;
    });
  }

  // ─────────────────────────────────────────────────────────────
  //  11. COUNTER — 3D Reflective Ward + Retaliation Singularity
  // ─────────────────────────────────────────────────────────────
  private _executeCounter(config: AbilityConfig, target: GameEntity | undefined) {
    const { payload = {} } = config;
    const windowMs: number = payload.windowDuration ?? 1400;
    const damage = this._resolveDamage(config, 36);
    const owner = this.character;
    const scene = owner.scene as any;
    const colorHex = this._resolveColor(config);

    const startHp = owner.currentHp;
    owner.immunities.add('PHYSICAL');
    this._floatingText(owner.sprite.x, owner.sprite.y - 55, `${config.name} [COUNTER]`, colorHex);

    this.threeVfx?.spawnBarrier({
      getPos: () => ({ x: owner.sprite.x, y: owner.sprite.y, active: owner.isAlive }),
      radiusPx: 75,
      durationMs: windowMs,
      color: colorHex
    });

    scene.time.delayedCall(windowMs, () => {
      owner.immunities.delete('PHYSICAL');
      if (!owner.isAlive || !target?.sprite) return;
      const dist = Phaser.Math.Distance.Between(owner.sprite.x, owner.sprite.y, target.sprite.x, target.sprite.y);
      if (owner.currentHp < startHp || dist < 260) {
        this.threeVfx?.spawnSingularity({
          x: target.sprite.x,
          y: target.sprite.y,
          stacks: 2,
          color: colorHex
        });
        const actual = target.receiveDamage(damage, config.archetype ?? 'COUNTER', owner);
        if (actual > 0) owner.onDamageDealt?.(actual);
        this._applyStatusEffects(config, target);
      }
    });
  }

  // ─────────────────────────────────────────────────────────────
  //  12. TERRAIN — 3D Erupting Cursed Pillar + AoE Launch
  // ─────────────────────────────────────────────────────────────
  private _executeTerrain(config: AbilityConfig, target: GameEntity | undefined) {
    const { payload = {}, castTime = 220 } = config;
    const damage = this._resolveDamage(config, 30);
    const duration: number = payload.duration ?? 3500;
    const owner = this.character;
    const scene = owner.scene as any;
    const colorHex = this._resolveColor(config);

    const pillarX = target?.sprite ? target.sprite.x : owner.sprite.x + (owner.sprite.flipX ? -150 : 150);
    const pillarY = target?.sprite ? target.sprite.y : owner.sprite.y;

    this._floatingText(owner.sprite.x, owner.sprite.y - 55, config.name, colorHex);

    scene.time.delayedCall(castTime, () => {
      if (!owner.isAlive) return;

      this.threeVfx?.spawnPillar({
        x: pillarX,
        y: pillarY,
        widthPx: 70,
        heightPx: 140,
        durationMs: duration,
        color: colorHex
      });

      this._spawnHitbox(pillarX, pillarY, 0, 80, 120, damage, config);
      if (target?.sprite) {
        const dist = Math.abs(target.sprite.x - pillarX);
        if (dist < 90) {
          (target.sprite.body as Phaser.Physics.Arcade.Body)?.setVelocityY(-520);
          this._applyStatusEffects(config, target);
        }
      }
    });
  }

  // ─────────────────────────────────────────────────────────────
  //  13. TRANSFORMATION — 3D Awakening Burst + CE Overdrive
  // ─────────────────────────────────────────────────────────────
  private _executeTransformation(config: AbilityConfig) {
    const { payload = {} } = config;
    const owner = this.character;
    const colorHex = this._resolveColor(config);
    const formName: string = payload.formName || config.name;
    const duration: number = payload.duration ?? 6000;

    this._floatingText(owner.sprite.x, owner.sprite.y - 65, `AWAKEN: ${formName.toUpperCase()}`, colorHex);
    owner.cursedEnergy.current = owner.cursedEnergy.max;
    owner.currentHp = Math.min(owner.maxHp, owner.currentHp + 20);

    this.threeVfx?.spawnSingularity({
      x: owner.sprite.x,
      y: owner.sprite.y,
      stacks: 3,
      color: colorHex
    });
    this.threeVfx?.spawnBarrier({
      getPos: () => ({ x: owner.sprite.x, y: owner.sprite.y, active: owner.isAlive }),
      radiusPx: 70,
      durationMs: duration,
      color: colorHex
    });
  }

  // ─────────────────────────────────────────────────────────────
  //  14. TETHER — 3D Cursed Chain Helix + Magnetic Pull
  // ─────────────────────────────────────────────────────────────
  private _executeTether(config: AbilityConfig, target: GameEntity | undefined) {
    const { payload = {}, castTime = 180 } = config;
    const damage = this._resolveDamage(config, 22);
    const duration: number = payload.duration ?? 2500;
    const owner = this.character;
    const scene = owner.scene as any;
    const colorHex = this._resolveColor(config);

    if (!target?.sprite) return;

    this._floatingText(owner.sprite.x, owner.sprite.y - 55, config.name, colorHex);
    this.threeVfx?.spawnTether({
      getCasterPos: () => ({ x: owner.sprite.x, y: owner.sprite.y, active: owner.isAlive }),
      getTargetPos: () => ({ x: target.sprite.x, y: target.sprite.y, active: target.isAlive }),
      durationMs: duration,
      color: colorHex
    });

    scene.time.delayedCall(castTime, () => {
      if (!owner.isAlive || !target.isAlive) return;
      const actual = target.receiveDamage(damage, config.archetype ?? 'BINDING', owner);
      if (actual > 0) owner.onDamageDealt?.(actual);

      // Pull target toward caster
      const pullDir = owner.sprite.x < target.sprite.x ? -1 : 1;
      (target.sprite.body as Phaser.Physics.Arcade.Body)?.setVelocity(pullDir * 380, -180);
      this._applyStatusEffects(config, target);
    });
  }

  // ─────────────────────────────────────────────────────────────
  //  15. COMMAND (Cursed Speech) — 3D Sonic Shockwave Cones
  // ─────────────────────────────────────────────────────────────
  private _executeCommand(config: AbilityConfig, target: GameEntity | undefined) {
    const { payload = {}, castTime = 150 } = config;
    const damage = this._resolveDamage(config, 28);
    const hearingRange: number = payload.hearingRange ?? 450;
    const owner = this.character;
    const scene = owner.scene as any;
    const colorHex = this._resolveColor(config);

    owner.throatStrain = Math.min(100, (owner.throatStrain || 0) + (payload.throatStrainCost ?? 20));
    const dir = owner.sprite.flipX ? -1 : 1;

    this._floatingText(owner.sprite.x, owner.sprite.y - 60, `"${config.name.toUpperCase()}!"`, colorHex);

    scene.time.delayedCall(castTime, () => {
      if (!owner.isAlive) return;

      this.threeVfx?.spawnSonicWave({
        x: owner.sprite.x + dir * 24,
        y: owner.sprite.y,
        dir,
        rangePx: hearingRange,
        color: colorHex
      });

      if (target?.sprite && target.isAlive) {
        const dist = Phaser.Math.Distance.Between(owner.sprite.x, owner.sprite.y, target.sprite.x, target.sprite.y);
        if (dist <= hearingRange) {
          const actual = target.receiveDamage(damage, config.archetype ?? 'COMMAND', owner);
          if (actual > 0) owner.onDamageDealt?.(actual);
          (target.sprite.body as Phaser.Physics.Arcade.Body)?.setVelocity(dir * 420, -240);
          this._applyStatusEffects(config, target);
        }
      }
    });
  }

  // ─────────────────────────────────────────────────────────────
  //  Internal helpers
  // ─────────────────────────────────────────────────────────────

  private _detonateStacks(target: GameEntity, stackKey: string, burstDamage: number, sourceConfig: AbilityConfig) {
    const stacks = target.debuffStacks.get(stackKey) ?? 0;
    const total = burstDamage + stacks * 8;
    const colorHex = this._resolveColor(sourceConfig);
    target.debuffStacks.set(stackKey, 0);

    this.threeVfx?.spawnSingularity({
      x: target.sprite.x,
      y: target.sprite.y,
      stacks: Math.max(2, stacks),
      color: colorHex
    });
    this._voidCollapse(target.sprite.x, target.sprite.y, stacks);
    const actualDmg = target.receiveDamage(total, sourceConfig.archetype ?? 'VOID', this.character);
    if (actualDmg > 0) {
      this.character.onDamageDealt?.(actualDmg);
      target.applyStatus?.('CE_NULLIFIED', 3000);
      (target.sprite.body as Phaser.Physics.Arcade.Body)?.setVelocity(
        this.character.sprite.x < target.sprite.x ? 500 : -500,
        -400
      );
    }
    this._floatingText(target.sprite.x, target.sprite.y - 60, `COLLAPSE ×${stacks}`, colorHex);
  }

  private _findOwnedStackKey(target: GameEntity | undefined): string {
    if (!target) return `${this.character.id}:Ability2`;
    for (const slot of ['Ability1', 'Ability2', 'Ability3']) {
      const key = `${this.character.id}:${slot}`;
      if ((target.debuffStacks.get(key) ?? 0) > 0) return key;
    }
    return `${this.character.id}:Ability2`;
  }

  private _applyStatusEffects(config: AbilityConfig, target: GameEntity) {
    if (!config.statusEffects?.length) return;
    for (const se of config.statusEffects) {
      if (Math.random() <= se.chance) {
        target.applyStatus?.(se.statusId, se.duration ?? 3000);
      }
    }
  }

  private _spawnHitbox(x: number, y: number, dir: number, w: number, h: number, damage: number, config: AbilityConfig) {
    const scene = this.character.scene as any;
    const hb = scene.hitboxes.create(x, y, undefined) as Phaser.Physics.Arcade.Sprite;
    hb.setVisible(false).setDisplaySize(w, h);
    const body = hb.body as Phaser.Physics.Arcade.Body;
    body.setAllowGravity(false);
    body.setImmovable(true);
    body.setSize(w, h);
    (hb as any).owner = this.character;
    (hb as any).damage = damage;
    (hb as any).archetype = config.archetype ?? 'VOID';
    (hb as any).facingDir = dir;
    scene.time.delayedCall(200, () => { if (hb?.active) hb.destroy(); });
  }

  // ─────────────────────────────────────────────────────────────
  //  Summon spawn implementations
  // ─────────────────────────────────────────────────────────────

  private _spawnChaseSummon(
    target: GameEntity, w: number, h: number, damage: number,
    duration: number, config: AbilityConfig, archetype: string
  ) {
    const scene = this.character.scene as any;
    const dir = this.character.sprite.x < target.sprite.x ? 1 : -1;
    const startX = this.character.sprite.x + dir * 20;
    const startY = this.character.sprite.y;
    const texKey: string | null = config.payload?.texture ?? null;
    const colorHex = this._resolveColor(config);

    const hb = scene.hitboxes.create(startX, startY, undefined) as Phaser.Physics.Arcade.Sprite;
    hb.setVisible(false).setDisplaySize(w, h);
    const body = hb.body as Phaser.Physics.Arcade.Body;
    body.setAllowGravity(false);
    body.setImmovable(false);
    body.setSize(w, h);
    (hb as any).owner = this.character;
    (hb as any).damage = damage;
    (hb as any).archetype = archetype;
    (hb as any).facingDir = dir;

    // 3D energy construct tracking the summon in Three.js
    this.threeVfx?.spawnProjectile({
      getPos: () => ({ x: hb.x, y: hb.y, active: Boolean(hb?.active) }),
      dir,
      color: colorHex,
      shape: 'METEOR',
      radiusPx: Math.max(w, h),
      maxDurationMs: duration
    });

    let visual: Phaser.GameObjects.GameObject | null = null;
    if (texKey && scene.textures.exists(texKey)) {
      const spr = scene.add.sprite(startX, startY, texKey)
        .setScale(0.5).setDepth(3).setFlipX(dir === -1);
      spr.play?.(`${texKey}_idle`, true);
      visual = spr;
    }

    const chaseTimer = scene.time.addEvent({
      delay: 32,
      loop: true,
      callback: () => {
        if (!hb.active || !target.isAlive || !target.sprite) { chaseTimer.remove(); return; }
        const dx = target.sprite.x - hb.x;
        const dy = target.sprite.y - hb.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        const speed = config.payload?.speed ?? 320;
        if (dist > 5) body.setVelocity((dx / dist) * speed, (dy / dist) * speed);
        (visual as any)?.setPosition(hb.x, hb.y);
      }
    });

    scene.time.delayedCall(duration, () => {
      chaseTimer.remove();
      if (hb?.active) hb.destroy();
      (visual as any)?.destroy?.();
    });
  }

  private _spawnDiveSummon(
    target: GameEntity, w: number, h: number, damage: number,
    _duration: number, config: AbilityConfig, archetype: string,
    knockback?: { x: number; y: number }
  ) {
    const scene = this.character.scene as any;
    const landX = target.sprite.x;
    const startY = 0;
    const colorHex = this._resolveColor(config);
    const colorNum = this._resolveColorNum(config);

    // 3D Sky Thunderbolt Pillar
    this.threeVfx?.spawnPillar({
      x: landX,
      y: target.sprite.y - 80,
      widthPx: w * 1.2,
      heightPx: 260,
      durationMs: 650,
      color: colorHex,
      fromSky: true
    });

    const hb = scene.hitboxes.create(landX, startY, undefined) as Phaser.Physics.Arcade.Sprite;
    hb.setVisible(false).setDisplaySize(w, h);
    const body = hb.body as Phaser.Physics.Arcade.Body;
    body.setAllowGravity(false);
    body.setImmovable(true);
    body.setSize(w, h);
    (hb as any).owner = this.character;
    (hb as any).damage = damage;
    (hb as any).archetype = archetype;
    (hb as any).facingDir = 0;

    scene.tweens.add({
      targets: hb,
      y: target.sprite.y,
      duration: 380,
      ease: 'Power3',
      onUpdate: () => { body.reset(hb.x, hb.y); },
      onComplete: () => {
        this._voidBurst(landX, target.sprite.y, colorNum, 60);
        if (knockback) {
          (target.sprite.body as Phaser.Physics.Arcade.Body)?.setVelocity(
            this.character.sprite.x < target.sprite.x ? knockback.x : -knockback.x,
            knockback.y
          );
        }
        scene.time.delayedCall(80, () => { if (hb?.active) hb.destroy(); });
      }
    });
  }

  private _spawnBossSummon(
    target: GameEntity | undefined, _w: number, _h: number, _damage: number,
    duration: number, config: AbilityConfig, _archetype: string,
    _knockback?: { x: number; y: number }
  ) {
    const scene = this.character.scene as any;
    const { width } = scene.scale;
    const owner = this.character;
    const floorY = owner.sprite.y;
    const colorHex = this._resolveColor(config);
    const colorNum = this._resolveColorNum(config);
    const spawnX = target
      ? target.sprite.x + (owner.sprite.x < target.sprite.x ? 100 : -100)
      : width / 2;

    this.threeVfx?.spawnAreaZone({
      x: spawnX,
      y: floorY,
      radiusPx: 130,
      durationMs: 2200,
      color: colorHex
    });

    [0, 250, 500, 900].forEach(delay => {
      scene.time.delayedCall(delay, () => {
        this._voidBurst(spawnX, floorY, colorNum, 70 + delay / 10);
        scene.cameras.main.shake(55, 0.004);
      });
    });
    this._floatingText(width / 2, floorY - 120, `${config.name.toUpperCase()}`, colorHex);

    scene.time.delayedCall(1400, () => {
      if (!owner.isAlive) return;

      this.threeVfx?.spawnSingularity({
        x: spawnX,
        y: floorY,
        stacks: 4,
        color: colorHex
      });

      const mahoraga = new MaharagaSummon(scene, owner);
      mahoraga.spawn(spawnX, floorY);
      scene.entities?.push(mahoraga);

      if (scene.platforms) {
        scene.physics.add.collider(mahoraga.sprite, scene.platforms);
      }

      if (scene.hitboxes) {
        scene.physics.add.overlap(
          scene.hitboxes,
          mahoraga.sprite,
          (hb: any, _sprite: any) => {
            if ((hb as any).owner === mahoraga) return;
            scene.handleHitOverlap?.(hb, mahoraga.sprite);
          },
          undefined,
          scene
        );
      }

      scene.time.delayedCall(duration, () => {
        if (!mahoraga.isAlive) return;
        this._voidBurst(mahoraga.sprite?.x ?? spawnX, floorY, colorNum, 90);
        mahoraga.despawn();
        if (scene.entities) {
          const idx = scene.entities.indexOf(mahoraga);
          if (idx !== -1) scene.entities.splice(idx, 1);
        }
      });
    });
  }

  // ─────────────────────────────────────────────────────────────
  //  2D Overlay VFX helpers
  // ─────────────────────────────────────────────────────────────

  private _voidBurst(x: number, y: number, color: number, radius: number) {
    const scene = this.character.scene as any;
    const ring = scene.add.circle(x, y, radius, color, 0.22).setDepth(50);
    const outline = scene.add.circle(x, y, radius, color, 0).setDepth(51);
    outline.setStrokeStyle(3, color, 0.9);
    scene.tweens.add({
      targets: [ring, outline], scaleX: 2.5, scaleY: 2.5, alpha: 0,
      duration: 380, ease: 'Power2',
      onComplete: () => { ring.destroy(); outline.destroy(); }
    });
  }

  private _voidCollapse(x: number, y: number, stacks: number) {
    const scene = this.character.scene as any;
    const baseColor = this._resolveColorNum();
    const colors = [baseColor, 0x6d28d9, 0x7c3aed, 0xa78bfa];
    [0, 80, 160, 220].slice(0, Math.max(1, stacks)).forEach((delay, i) => {
      scene.time.delayedCall(delay, () =>
        this._voidBurst(x + Phaser.Math.Between(-18, 18), y + Phaser.Math.Between(-18, 18),
          colors[i % colors.length], 55 + i * 18)
      );
    });
    scene.cameras.main.shake(280, 0.011);
  }

  private _floatingText(x: number, y: number, text: string, color: string) {
    const scene = this.character.scene as any;
    const txt = scene.add.text(x, y, text, {
      fontFamily: 'Share Tech Mono', fontSize: '17px', color,
      stroke: '#000000', strokeThickness: 3
    }).setOrigin(0.5).setDepth(80);
    scene.tweens.add({ targets: txt, y: y - 55, alpha: 0, duration: 1100, onComplete: () => txt.destroy() });
  }
}
